    const p = JSON.parse(argv[0]);
    $.CGEventPost(0, $.CGEventCreateMouseEvent($(), 5, $.CGPointMake(p.x, p.y), 0));
    for (let i = 0; i < Math.max(Math.abs(p.dy), Math.abs(p.dx)); i++) {
